import { clock, duration, OLD_SHIFTS, SOURCE_URL, RULE_VERSION, PLAN_VERSION, TASK_LIMITS } from './standby-calculator.js?v=20261011-r5';

export function showStandby({root,api,esc,json,toast,getSnapshot,isStale,onChange,key}){
  let saved;try{saved=JSON.parse(localStorage.getItem(key)||'null');}catch{}
  const snapshot=getSnapshot();let state=structuredClone((saved?.modifiedAt>snapshot?.modifiedAt?saved:snapshot)||saved||{duties:[],confirmed:false}),report=null,comparison=null,busy=false,run=0,resultFilter='all';
  state.options||={model:'user-four-hour',leadMinutes:45,minimumBuffer:30,maxMinutes:420};state.shifts||=structuredClone(OLD_SHIFTS);
  state.schemeView||=state.manualRevision?'revision':'original';
  const migrated=state.ruleVersion!==RULE_VERSION||state.planVersion!==PLAN_VERSION;if(migrated){state.options.model='user-four-hour';state.baseSummary=null;if(state.baseOptions)state.baseOptions.model='user-four-hour';}
  const persist=()=>{state.ruleVersion=RULE_VERSION;state.planVersion=PLAN_VERSION;state.modifiedAt=new Date().toISOString();try{localStorage.setItem(key,JSON.stringify(state));}catch{}onChange(structuredClone(state));};
  const stale=()=>state.sourceKind==='timetable'&&isStale(state);
  const displayTitle=()=>/^[a-f\d]{32}$/i.test(state.title||'')?'已确认航班':state.title||'冬季航班';
  const payload=()=>({duties:state.duties,options:state.options,shifts:state.shifts,baseShifts:state.manualRevision?state.baseShifts:undefined,title:displayTitle()+' 备份时段方案',sourceName:state.sourceName});
  const usable=()=>state.confirmed&&!stale()&&state.duties?.length;
  const invalidate=()=>{report=null;comparison=null;run++;persist();};
  const edited=()=>{invalidate();root.querySelector('#standbyWord').disabled=true;root.querySelector('#standbyExcel').disabled=true;drawComparison();drawGoal();drawRevision();drawResults();};
  function draw(){
    root.innerHTML=`<section class="flight-heading"><div><p class="eyebrow">实用工具 / <a href="/flights">航班时刻表</a> / 备份方案</p><h1>备份时段方案</h1></div><div class="actions"><label class="button secondary flight-upload">导入已确认 Excel<input id="standbyUpload" type="file" accept=".xlsx" aria-label="导入已确认 Excel"></label></div></section>
    <section class="flight-result-pane"><div class="pane-title"><div><h2>1 · 已确认航班版本</h2><p class="meta">${esc(state.sourceName||'从航班时刻表确认后进入，或导入现有 Excel。')}${state.confirmedAt?' · '+esc(new Date(state.confirmedAt).toLocaleString('zh-CN')):''}</p></div><div class="standby-source-actions"><span class="badge">${state.duties?.length||0} 组</span><button class="ghost small" id="clearStandby">清空本次分析</button></div></div>
    ${stale()?'<p class="notice">航班时刻表已修改，请返回重新确认后计算。</p>':state.confirmed?'':'<p class="notice">请核对航班组合、安排和 BFTM，再确认用于分析。</p>'}
    <details ${state.confirmed?'':'open'}><summary>查看航班组合与开会时间</summary><div class="flight-scroll standby-source"><table class="flight-table"><thead><tr><th>航点</th><th>航班组合</th><th>人工安排</th><th>航段</th><th>BFTM</th><th>本次任务 STA</th></tr></thead><tbody>${(state.duties||[]).map(d=>`<tr><td>${esc(d.point)}</td><td>${esc(d.label)}</td><td>${d.type==='layover'?'过夜去程':'当天往返'}</td><td>${d.sectors}</td><td>${clock(d.briefing)}</td><td>${clock(d.arrival)}</td></tr>`).join('')}</tbody></table></div></details>${!state.confirmed&&state.duties?.length?'<div class="pair-actions"><label><input id="standbyTimeZone" type="checkbox"> 确认时间全部是澳门／北京时间，且去回程、过夜及开会时间已核对</label><button id="confirmStandbySource" disabled>确认这份时刻表</button></div>':''}</section>
    <section class="flight-result-pane"><div class="pane-title"><div><h2>2 · 备份方案</h2></div></div><div id="standbyGoal" aria-live="polite"></div><div class="standby-controls"><label>计算规则<select id="standbyModel"><option value="user-four-hour">指定四小时规则</option><option value="airport">其他算法：从备份开始起算</option></select></label><label>提前 BFTM（分钟）<input id="standbyLead" type="number" min="45" max="180" value="${state.options.leadMinutes}"></label><label>最低 buffer（分钟）<input id="standbyBuffer" type="number" min="30" max="180" value="${state.options.minimumBuffer}"></label><label>单段最多（小时）<input id="standbyMax" type="number" min="1" max="7" step="0.25" value="${state.options.maxMinutes/60}"></label><button id="generateStandby" ${usable()&&!busy?'':'disabled'}>${busy?'正在搜索…':state.manualRevision?'重新自动排时段':'生成全覆盖方案'}</button></div>
    <details class="standby-rule-details"><summary>查看计算规则 · 往返 ≤14:00／过夜 ≤09:00</summary><p class="meta standby-rule">备份开始到 BFTM ≤4 小时：FDP 从 BFTM 起算。&gt;4 小时：从备份开始＋4 小时起算。两种情况下 FDP MAX 均取 Table A 中备份开始与 BFTM 对应航段列的较小值。总时长独立从原备份开始至本次 STA 判断：往返 ≤14:00／过夜 ≤09:00。正常和备份 buffer 均须达到最低值，优选 &gt;01:00。<a href="${SOURCE_URL}" target="_blank" rel="noopener">查看 Table A 来源</a></p></details><div id="standbyComparisons"></div></section>
    <section class="flight-result-pane"><div class="pane-title"><div><h2>3 · 方案版本</h2></div></div><div class="standby-version-tabs" role="group" aria-label="方案版本"><button id="viewOriginal" class="secondary">原方案</button><button id="viewRevision" class="secondary">人工修订方案${state.manualRevision?' · 已修改':''}</button></div><div id="standbyOriginal"></div><div id="standbyEditor"><div class="pane-title"><div><h3>人工修订方案</h3></div><div class="actions standby-result-actions"><button id="recalculateStandby" class="secondary" ${usable()&&!busy?'':'disabled'}>生成修订方案</button><button id="standbyWord" ${report&&!busy?'':'disabled'}>下载方案 Word</button><button id="standbyExcel" class="secondary" ${report&&!busy?'':'disabled'}>下载 FDP Excel</button></div></div><div class="standby-shifts">${state.shifts.map((s,i)=>`<div class="standby-shift"><b>${esc(s.name)}</b><label>开始<input aria-label="${esc(s.name)} 开始" data-shift="${i}" data-edge="start" type="time" value="${s.start.slice(0,2)}:${s.start.slice(2)}"></label><span>—</span><label>结束<input aria-label="${esc(s.name)} 结束" data-shift="${i}" data-edge="end" type="time" value="${s.end.slice(0,2)}:${s.end.slice(2)}"></label></div>`).join('')}</div><div id="standbyRevision" aria-live="polite"></div><div id="standbyResult" aria-live="polite"></div></div></section>`;
    root.querySelector('#standbyModel').value=state.options.model;root.querySelector('#viewOriginal').onclick=()=>{state.schemeView='original';persist();draw();};root.querySelector('#viewRevision').onclick=()=>{state.schemeView='revision';persist();draw();};
    root.querySelector('#standbyUpload').onchange=importFile;root.querySelector('#clearStandby').onclick=()=>{state={duties:[],confirmed:false,options:state.options,shifts:structuredClone(OLD_SHIFTS)};invalidate();draw();toast('本次分析已清空，原始文件和已保存航班表仍可使用');};
    root.querySelector('#standbyTimeZone')?.addEventListener('change',e=>root.querySelector('#confirmStandbySource').disabled=!e.target.checked);
    root.querySelector('#confirmStandbySource')?.addEventListener('click',()=>{state.confirmed=true;state.confirmedAt=new Date().toISOString();persist();draw();});
    for(const [id,name,multiplier] of [['standbyModel','model',0],['standbyLead','leadMinutes',1],['standbyBuffer','minimumBuffer',1],['standbyMax','maxMinutes',60]]){const input=root.querySelector('#'+id),update=e=>{state.options[name]=multiplier?Number(e.target.value)*multiplier:e.target.value;edited();};input.oninput=update;input.onchange=e=>{update(e);draw();};}
    root.querySelectorAll('[data-shift]').forEach(input=>{const update=e=>{state.baseShifts||=structuredClone(state.shifts);state.baseOptions||=structuredClone(state.options);state.manualRevision=true;state.schemeView='revision';state.shifts[Number(input.dataset.shift)][input.dataset.edge]=e.target.value.replace(':','');edited();};input.oninput=update;input.onchange=e=>{update(e);draw();};});
    root.querySelector('#generateStandby').onclick=()=>calculate(true);root.querySelector('#recalculateStandby').onclick=()=>calculate(false);
    root.querySelector('#standbyWord').onclick=e=>download('docx',e.currentTarget);root.querySelector('#standbyExcel').onclick=e=>download('xlsx',e.currentTarget);
    root.querySelector('#clearStandby').disabled=busy;if(busy)root.querySelectorAll('input,select').forEach(node=>node.disabled=true);drawVersions();drawGoal();drawComparison();drawRevision();drawResults();
  }
  function drawRevision(){
    const target=root.querySelector('#standbyRevision');if(!target)return;
    const rev=report?.revision;
    target.innerHTML=rev?`<div class="standby-revision"><b>修订方案已生成 · ${report.goal.achieved?'全覆盖':'保留 '+report.selected.missing.length+' 组缺口'}</b><p>按当前规则比较：修改前 ${rev.baseline.covered}/${report.selected.total} → 修改后 ${report.selected.covered}/${report.selected.total}。新增缺口 ${rev.newlyUncovered.length} 组，恢复覆盖 ${rev.restored.length} 组。</p><div>${rev.changes.map(c=>`<span><b>${esc(c.name)}</b> ${c.before?c.before.start+'–'+c.before.end:'无'} → ${c.after?c.after.start+'–'+c.after.end:'删除'}</span>`).join('')}</div></div>`:state.manualRevision?'<p class="standby-revision">时段已修改，请生成修订方案。</p>':'';
  }
  function drawVersions(){
    const original=state.schemeView==='original';root.querySelector('#standbyOriginal').hidden=!original;root.querySelector('#standbyEditor').hidden=original;
    root.querySelector('#viewOriginal').setAttribute('aria-pressed',String(original));root.querySelector('#viewRevision').setAttribute('aria-pressed',String(!original));
    const summary=state.baseSummary;
    root.querySelector('#standbyOriginal').innerHTML=state.baseShifts?`<div class="pane-title"><div><h3>原方案 · ${state.baseShifts.length} 个备份</h3></div><div class="actions standby-result-actions"><button id="originalWord" class="secondary" ${usable()&&summary&&!busy?'':'disabled'}>下载原方案 Word</button><button id="originalExcel" class="secondary" ${usable()&&summary&&!busy?'':'disabled'}>下载原方案 Excel</button></div></div><div class="standby-original-times">${state.baseShifts.map(s=>`<div><b>${esc(s.name)}</b><span>${s.start}–${s.end}</span></div>`).join('')}</div>${summary?`<div class="standby-summary"><b>原方案覆盖 ${summary.covered}/${summary.total} 组</b><span>${summary.total-summary.covered} 组缺口</span><span>最小通过 buffer ${summary.lowest===null?'—':duration(summary.lowest)}</span></div>`:''}<div class="standby-original-action"><button id="editOriginal" ${busy?'disabled':''}>编辑并生成修订方案</button></div>`:'<p class="flight-empty">生成或选定方案后，这里保留原方案；在“人工修订方案”中编辑时间。</p>';
    root.querySelector('#editOriginal')?.addEventListener('click',()=>{state.schemeView='revision';persist();draw();});
    root.querySelector('#originalWord')?.addEventListener('click',e=>download('docx',e.currentTarget,true));root.querySelector('#originalExcel')?.addEventListener('click',e=>download('xlsx',e.currentTarget,true));
  }
  function drawMissingCards(){
    const target=root.querySelector('#standbyResult'),s=report.selected;
    target.querySelector('.flight-scroll').outerHTML=s.missing.length?`<div class="standby-missing-cards">${s.missing.map(r=>`<article class="standby-missing-card"><div><h3>${esc(r.label)}</h3><span class="badge standby-warning">${report.revision?.newlyUncovered.includes(r.id)?'新增缺口':'未覆盖'}</span></div><p class="meta">${esc(r.point)} · ${r.type==='layover'?'过夜去程':'当天往返'} · BFTM ${clock(r.briefing)} · STA ${clock(r.arrival)}</p><div class="standby-gap-reasons">${r.results.map(x=>`<p><b>${esc(x.shift)}</b> ${esc(x.reason)}</p>`).join('')}</div><details><summary>查看每个备份的 FDP 计算</summary>${r.results.map(x=>`<p class="meta">${esc(x.shift)} ${clock(x.standbyStart)}–${clock(x.standbyEnd)}：${clock(x.start)}＋${duration(x.limit)}－${clock(r.arrival)}＝${duration(x.buffer)}；开始至 STA ${duration(x.standbyElapsed)}／上限 ${duration(x.elapsedLimit)}。</p>`).join('')}</details></article>`).join('')}</div>`:'';
  }
  function drawGoal(){
    const original=state.schemeView==='original',s=original&&state.baseSummary?{...state.baseSummary,shifts:state.baseShifts,missing:Array(state.baseSummary.total-state.baseSummary.covered)}:report?.selected,full=s?.covered===s?.total&&!!s;
    root.querySelector('#standbyGoal').innerHTML=`<div class="standby-goal ${s?full?'is-complete':'is-incomplete':''}"><div><span class="standby-goal-label">${original?'原方案':'人工修订方案'} · 全部已确认组合</span><h3>${busy?'正在计算可接替时段':s?full?'已实现全覆盖':'当前方案有 '+s.missing.length+' 组未覆盖':'全覆盖优先，4–6 个备份优先'}</h3><p>${s?esc(full?`全部 ${s.total} 组均有可接替备份，使用 ${s.shifts.length} 个待命时段。`:original?'原方案存在覆盖缺口，可切换人工修订方案调整时间。':report?.proposal.completePossible?'当前人工时段存在缺口，已保留修订结果，可查看未覆盖航班并导出。':report?.proposal.explanation||'当前时段尚未全覆盖，可查看并导出缺口。'):'待命按需执飞；每组任务至少有一套合格备份可接替。'}</p></div>${s?`<div class="standby-goal-number"><b>${s.covered}<small> / ${s.total}</small></b><span>${s.shifts.length} 个备份 · ${s.missing.length} 组缺口</span></div>`:''}</div>`;
  }
  function drawComparison(){
    const target=root.querySelector('#standbyComparisons');if(!comparison){target.innerHTML='';return;}
    const proposal=comparison.proposal,items=proposal.schemes;
    const chosen=s=>JSON.stringify(s.shifts)===JSON.stringify(state.schemeView==='original'?state.baseShifts||state.shifts:state.shifts);
    target.innerHTML=`<div class="standby-comparisons">${items.map((s,i)=>`<article class="standby-card ${chosen(s)?'is-selected':''}"><div class="standby-card-top"><h3>${s.shifts.length}<small> 个备份</small></h3><span class="badge ${s.covered===s.total?'':'standby-warning'}">${s.covered===s.total?'全覆盖':'缺口 '+s.missing.length}</span></div><p><b>${s.covered}/${s.total}</b> 组可接替</p><p class="meta">最小通过 buffer ${s.lowest===null?'—':duration(s.lowest)}</p><details><summary>查看 ${s.shifts.length} 个待命时段</summary><div class="standby-card-times">${s.shifts.map(x=>`<span><b>${esc(x.name)}</b> ${x.start}–${x.end}</span>`).join('')}</div></details><button class="${chosen(s)?'':'secondary'}" data-scheme="${i}" aria-pressed="${chosen(s)}" ${busy?'disabled':''}>${chosen(s)?'当前方案':s.covered===s.total?'选择全覆盖方案':'查看此候选'}</button></article>`).join('')}</div>
    <details class="standby-reason"><summary>数量选择与划分理由</summary><p>${esc(proposal.explanation)}</p><p>${proposal.minimumProven?`全部可接替任务最少需要 ${proposal.requiredCount} 个不同开始时段。`:`已找到 ${proposal.requiredCount} 个开始时段覆盖可接替任务，尚未证明数量最少。`}${proposal.requiredCount<4&&proposal.completePossible?'按你指定的 4–6 个范围，优先推荐 4 个；额外时段提供重叠可接替选择。':''}在全覆盖、优选 buffer 和最低 buffer 相同的条件下，优先分散开始时间。部分覆盖候选不保证覆盖数为全局最大。</p>${proposal.separateWindows.length?`<p class="meta">以下 ${proposal.separateWindows.length} 个互不重叠的可用开始范围构成数量下界；所有条件逐分钟检查。</p><div class="standby-proof">${proposal.separateWindows.map(w=>`<span><b>${esc(w.label)}</b><span>${clock(w.first)}–${clock(w.last)}</span></span>`).join('')}</div>`:''}</details>
    <details class="standby-reason"><summary>与原五个时段比较 · 覆盖 ${comparison.original.covered}/${comparison.original.total}</summary><p class="meta">${comparison.original.shifts.map(x=>`${x.name} ${x.start}–${x.end}`).join(' / ')} · 最小通过 buffer ${comparison.original.lowest===null?'—':duration(comparison.original.lowest)}</p><button class="secondary small" id="useOriginal" ${busy?'disabled':''}>计算原五个时段</button></details>
    ${proposal.impossible.length?`<div class="standby-conflicts"><h3>${proposal.impossible.length} 组规则冲突，增加备份也无法消除</h3>${proposal.impossible.map(d=>`<details><summary>${esc(d.label)} · BFTM ${clock(d.briefing)} · STA ${clock(d.arrival)}</summary><p>${esc(d.conflict.explanation)}</p><p>${esc(d.conflict.action)}</p></details>`).join('')}<a href="/flights">返回航班时刻表核对</a></div>`:''}`;
    const select=shifts=>{if(busy)return;state.shifts=structuredClone(shifts);state.baseShifts=structuredClone(shifts);state.manualRevision=false;state.baseOptions=structuredClone(state.options);state.baseSummary=null;state.schemeView='original';resultFilter='all';report=null;persist();return calculate(false);};
    target.querySelectorAll('[data-scheme]').forEach(b=>b.onclick=()=>select(items[Number(b.dataset.scheme)].shifts));target.querySelector('#useOriginal').onclick=()=>select(comparison.original.shifts);
  }
  function drawResults(){const target=root.querySelector('#standbyResult');if(!report){target.innerHTML='<p class="flight-empty">确认航班版本后生成方案，或计算当前时段。</p>';return;}
    const s=report.selected;
    target.innerHTML=`<div class="standby-summary"><b>覆盖 ${s.covered}/${s.total} 组</b><span>${s.missing.length} 组缺口</span><span>${s.preferred} 组 buffer &gt; 01:00</span><span>最小通过 buffer ${s.lowest===null?'—':duration(s.lowest)}</span></div>${s.missing.length?`<p class="notice">当前方案有 ${s.missing.length} 组没有合格备份。</p>`:''}${report.options.model!=='user-four-hour'?'<p class="notice">当前选择了其他起算算法；指定四小时规则请在计算规则中选择。14／9 小时硬条件仍适用。</p>':''}<div class="standby-result-filter" role="group" aria-label="航班覆盖筛选"><button class="secondary small" data-result-filter="all" aria-pressed="${resultFilter==='all'}">全部航班 ${s.total}</button><button class="secondary small" data-result-filter="missing" aria-pressed="${resultFilter==='missing'}">只看未覆盖航班 ${s.missing.length}</button></div>${resultFilter==='missing'&&!s.missing.length?'<p class="flight-empty">全部航班已有合格备份，没有覆盖缺口。</p>':''}<div class="flight-scroll"><table class="flight-table"><thead><tr><th>航点／组合</th><th>安排</th><th>BFTM</th><th>本次 STA</th><th>正常 buffer</th><th>建议备份</th><th>FDP 开始／上限</th><th>备份 buffer</th><th>开始至 STA／上限</th><th>状态</th></tr></thead><tbody>${s.rows.map((r,i)=>resultFilter==='missing'&&r.best?'':`<tr class="${r.best?r.best.preferred?'':'standby-tight':'standby-gap'}"><td><b>${esc(r.point)}</b><br>${esc(r.label)}<br><button class="ghost small" data-detail="${i}">查看逐备份计算</button></td><td>${r.type==='layover'?'过夜去程':'当天往返'} · ${r.sectors} 段</td><td>${clock(r.briefing)}</td><td>${clock(r.arrival)}</td><td>${duration(r.normal.buffer)}</td><td>${r.best?esc(r.best.shift)+' '+clock(r.best.standbyStart)+'–'+clock(r.best.standbyEnd):'无可用备份'}</td><td>${r.best?clock(r.best.start)+' / '+duration(r.best.limit):'—'}</td><td>${r.best?duration(r.best.buffer):'—'}</td><td>${r.best?duration(r.best.standbyElapsed):'—'} / ${duration(TASK_LIMITS[r.type])}</td><td>${!r.best?'未覆盖':r.best.preferred?'充足':'临界'}${!r.best?'<div class="standby-gap-reasons">'+r.results.map(x=>'<p><b>'+esc(x.shift)+'</b> '+esc(x.reason)+'</p>').join('')+'</div>':''}</td></tr><tr id="standbyDetail${i}" hidden><td colspan="10">${r.results.map(x=>`<p><b>${esc(x.shift)}</b> · ${clock(x.start)}＋${duration(x.limit)}－${clock(r.arrival)}＝<b>${duration(x.buffer)}</b> · 备份 ${clock(x.standbyStart)} 开始至 STA ${duration(x.standbyElapsed)} / 上限 ${duration(x.elapsedLimit)} · ${x.pass?'可接替':esc(x.reason)} · Table A ${esc(x.band)}</p>`).join('')}</td></tr>`).join('')}</tbody></table></div>`;if(resultFilter==='missing')drawMissingCards();target.querySelectorAll('[data-result-filter]').forEach(b=>b.onclick=()=>{resultFilter=b.dataset.resultFilter;drawResults();});target.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{const row=target.querySelector('#standbyDetail'+b.dataset.detail);row.hidden=!row.hidden;});
  }
  async function calculate(generate){if(!usable()||busy)return;busy=true;report=null;const token=++run;draw();try{const result=await api('/api/flights/standby/analyze',{method:'POST',...json({...payload(),shifts:generate?undefined:state.shifts,baseShifts:generate?undefined:payload().baseShifts,generate})});if(token!==run||!root.isConnected)return;comparison=result;if(generate){state.shifts=structuredClone(result.shifts);state.baseShifts=structuredClone(result.shifts);state.manualRevision=false;state.schemeView='original';resultFilter='all';}if(!state.manualRevision){state.baseShifts=structuredClone(result.shifts);state.baseOptions=structuredClone(state.options);state.baseSummary={covered:result.selected.covered,total:result.selected.total,lowest:result.selected.lowest};}else if(!state.baseSummary&&result.revision)state.baseSummary={covered:result.revision.baseline.covered,total:result.selected.total,lowest:result.revision.baseline.lowest};report=result;persist();}catch(e){toast(e.message,true);}finally{if(token===run){busy=false;if(root.isConnected)draw();}}}
  async function importFile(e){const file=e.target.files[0];if(!file||busy)return;const token=++run;busy=true;report=null;comparison=null;draw();try{const fd=new FormData();fd.append('file',file);const result=await api('/api/flights/standby/import',{method:'POST',body:fd});if(token!==run||!root.isConnected)return;state={duties:result.duties,sourceKind:'excel',sourceName:file.name,title:file.name.replace(/\.xlsx$/i,''),confirmed:false,options:state.options,shifts:structuredClone(OLD_SHIFTS),warnings:result.warnings};persist();toast('已读取航班表，请核对并确认时间口径');}catch(error){toast(error.message,true);}finally{if(token===run){busy=false;if(root.isConnected)draw();}}}
  async function download(format,button,original=false){if((original?!state.baseSummary:!report)||!usable()||busy)return;const token=run;button.disabled=true;try{const response=await fetch('/api/flights/standby/export/'+format,{method:'POST',headers:{'Content-Type':'application/json','x-session-token':sessionStorage.getItem('quizforge-session-token')||''},body:JSON.stringify(original?{...payload(),baseShifts:undefined,shifts:state.baseShifts,options:state.baseOptions||state.options,title:displayTitle()+' 备份时段原方案'}:payload())});if(!response.ok)throw Error((await response.json()).error||'生成失败');if(token!==run||!root.isConnected)return;const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download=displayTitle()+(original?'·原方案':report.revision?'·修订版':'·当前方案')+((original?state.baseSummary.covered===state.baseSummary.total:report.goal.achieved)?'':'·未全覆盖诊断')+(format==='docx'?'·备份方案说明':'·FDP buffer')+'.'+format;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('文件已生成');}catch(e){toast(e.message,true);}finally{if(token===run&&(original?state.baseSummary:report))button.disabled=false;}}
  if(migrated){persist();if(state.duties?.length)toast('已更新为四小时起算、FDP MAX 始终取两时段较小值；原方案和人工时段保留，请重新计算');}
  draw();return ()=>{run++;};
}
